"use client"
import React, { useState } from 'react'
import { Raffle } from '@/types/raffle'

const page = () => {
  const [raffles, setRaffles] = useState<Raffle[]>([])
  const [newRaffle, setNewRaffle] = useState({ name: '', description: '' });

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
    setNewRaffle({ ...newRaffle, [e.target.name]: e.target.value });
  };

  const handleAddRaffle = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newRaffle.name) return;
    const raffle: Raffle & { name: string; description: string } = {
      id: Date.now().toString(),
      entries: [],
      createdAt: new Date().toISOString(),
      name: newRaffle.name,
      description: newRaffle.description,
    };
    setRaffles([...raffles, raffle]);
    setNewRaffle({ name: '', description: '' });
  };

  return (
    <div className="max-w-xl mx-auto mt-8">
      <h2 className="text-xl font-bold mb-4">Neue Auslosung hinzufügen</h2>
      <form onSubmit={handleAddRaffle} className="flex flex-col gap-2 mb-8 p-4 border rounded-lg bg-white shadow">
        <input
          type="text"
          name="name"
          placeholder="Name der Auslosung"
          value={newRaffle.name}
          onChange={handleInputChange}
          className="border rounded p-2"
          required
        />
        <textarea
          name="description"
          placeholder="Beschreibung"
          value={newRaffle.description}
          onChange={handleInputChange}
          className="border rounded p-2"
        />
        <button type="submit" className="bg-snowblue text-white rounded p-2 hover:bg-snowblue/80">Hinzufügen</button>
      </form>
      <div>
        <h3 className="font-semibold mb-2">Aktuelle Raffles</h3>
        <ul>
          {raffles.length > 0 ? raffles.map((r) => (
            <li key={r.id} className="border-b py-2">{r.name} – {r.description}</li>
          )) : <li>Keine Raffles vorhanden</li>}
        </ul>
      </div>
    </div>
  )
}

export default page